//! Decides whether a copy must not be saved.

use std::sync::LazyLock;

use regex::Regex;

use crate::settings::Privacy;

/// Markers defined at http://nspasteboard.org and used by password managers.
pub const CONCEALED_TYPES: &[&str] = &[
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
    "com.agilebits.onepassword",
    "de.petermaurer.TransientPasteboardType",
    "com.typeit4me.clipping",
    "Pasteboard generator type",
];

static SECRET_PATTERNS: LazyLock<Vec<Regex>> = LazyLock::new(|| {
    [
        r"-----BEGIN (?:[A-Z]+ )?PRIVATE KEY-----",
        r"\bAKIA[0-9A-Z]{16}\b",
        r"\bgh[pousr]_[A-Za-z0-9]{36,}\b",
        r"\bgithub_pat_[A-Za-z0-9_]{40,}\b",
        r"\bxox[abprs]-[A-Za-z0-9-]{10,}",
        r"\bsk-ant-[A-Za-z0-9_-]{20,}",
        r"\bsk-(?:proj-)?[A-Za-z0-9_-]{32,}",
        r"\bAIza[0-9A-Za-z_-]{35}\b",
        r"\beyJ[A-Za-z0-9_-]{8,}\.eyJ[A-Za-z0-9_-]{8,}\.[A-Za-z0-9_-]{8,}",
    ]
    .iter()
    .map(|p| Regex::new(p).unwrap())
    .collect()
});

static CARD_RE: LazyLock<Regex> = LazyLock::new(|| Regex::new(r"^[0-9][0-9 -]{11,22}[0-9]$").unwrap());

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum IgnoreReason {
    Concealed(String),
    ExcludedApp(String),
    Secret,
    Pattern(String),
}

impl IgnoreReason {
    /// Concealed or secret-looking content, which may be kept briefly instead
    /// of skipped. Excluded apps and the user's own patterns never are.
    pub fn is_sensitive(&self) -> bool {
        matches!(self, IgnoreReason::Concealed(_) | IgnoreReason::Secret)
    }
}

/// What to do with copied text.
#[derive(Debug, PartialEq, Eq)]
pub enum Verdict {
    Save,
    Ignore(IgnoreReason),
    /// Save, but mark sensitive and remove after this many milliseconds.
    KeepBriefly(IgnoreReason, i64),
}

pub struct PrivacyFilter {
    settings: Privacy,
    patterns: Vec<Regex>,
}

impl PrivacyFilter {
    pub fn new(settings: &Privacy) -> PrivacyFilter {
        let patterns = settings
            .ignore_patterns
            .iter()
            .filter_map(|p| match Regex::new(p) {
                Ok(re) => Some(re),
                Err(e) => {
                    tracing::warn!("ignoring invalid privacy pattern {p:?}: {e}");
                    None
                }
            })
            .collect();
        PrivacyFilter { settings: settings.clone(), patterns }
    }

    /// Checked before reading any data, so concealed content is never loaded.
    pub fn check_types(&self, types: &[String], source_app: Option<&str>) -> Option<IgnoreReason> {
        if self.settings.ignore_concealed
            && let Some(t) = types.iter().find(|t| CONCEALED_TYPES.contains(&t.as_str()))
        {
            return Some(IgnoreReason::Concealed(t.clone()));
        }
        let app = source_app?;
        self.settings
            .excluded_apps
            .iter()
            .any(|a| a.eq_ignore_ascii_case(app))
            .then(|| IgnoreReason::ExcludedApp(app.to_string()))
    }

    /// How long sensitive items are kept, if the user opted in.
    pub fn sensitive_expiry_ms(&self) -> Option<i64> {
        let e = self.settings.sensitive_expiry.trim();
        (!e.is_empty()).then(|| crate::rules::parse_duration(e)).flatten()
    }

    /// Turns a skip reason into the final verdict, honoring the
    /// keep-sensitive-briefly setting.
    pub fn verdict(&self, reason: Option<IgnoreReason>) -> Verdict {
        match reason {
            None => Verdict::Save,
            Some(r) if r.is_sensitive() => match self.sensitive_expiry_ms() {
                Some(ms) => Verdict::KeepBriefly(r, ms),
                None => Verdict::Ignore(r),
            },
            Some(r) => Verdict::Ignore(r),
        }
    }

    /// The text decision: the user's own patterns win over secret detection,
    /// so a pattern match is never kept, even briefly.
    pub fn decide_text(&self, text: &str) -> Verdict {
        if let Some(re) = self.patterns.iter().find(|re| re.is_match(text)) {
            return Verdict::Ignore(IgnoreReason::Pattern(re.as_str().to_string()));
        }
        self.verdict((self.settings.ignore_secrets && looks_secret(text)).then_some(IgnoreReason::Secret))
    }

    #[cfg(test)]
    pub fn check_text(&self, text: &str) -> Option<IgnoreReason> {
        if self.settings.ignore_secrets && looks_secret(text) {
            return Some(IgnoreReason::Secret);
        }
        self.patterns.iter().find(|re| re.is_match(text)).map(|re| IgnoreReason::Pattern(re.as_str().to_string()))
    }
}

static PASSWORD_WORD: LazyLock<Regex> =
    LazyLock::new(|| Regex::new(r"(?i)\b(?:passwords?|passwd|pwd|passcode|passphrase)[0-9!@#$%^&*]*\b").unwrap());

/// Short snippets that mention a password, such as "user / Password1" or
/// "pwd: hunter2". Deliberately broad, so it is only used where the user opts in.
pub fn mentions_password(text: &str) -> bool {
    text.chars().count() <= 300 && PASSWORD_WORD.is_match(text)
}

pub fn looks_secret(text: &str) -> bool {
    if text.len() > 100_000 {
        return false;
    }
    if SECRET_PATTERNS.iter().any(|re| re.is_match(text)) {
        return true;
    }
    let t = text.trim();
    CARD_RE.is_match(t) && luhn(t)
}

fn luhn(s: &str) -> bool {
    let digits: Vec<u32> = s.chars().filter_map(|c| c.to_digit(10)).collect();
    if !(13..=19).contains(&digits.len()) {
        return false;
    }
    let sum: u32 = digits
        .iter()
        .rev()
        .enumerate()
        .map(|(i, &d)| {
            if i % 2 == 1 {
                let d = d * 2;
                if d > 9 { d - 9 } else { d }
            } else {
                d
            }
        })
        .sum();
    sum.is_multiple_of(10)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn concealed_and_excluded() {
        let f = PrivacyFilter::new(&Privacy::default());
        let types = vec!["public.utf8-plain-text".to_string(), "org.nspasteboard.ConcealedType".to_string()];
        assert!(matches!(f.check_types(&types, None), Some(IgnoreReason::Concealed(_))));
        let plain = vec!["public.utf8-plain-text".to_string()];
        assert_eq!(f.check_types(&plain, Some("com.apple.Safari")), None);
        assert!(matches!(f.check_types(&plain, Some("com.1password.1password")), Some(IgnoreReason::ExcludedApp(_))));
    }

    #[test]
    fn secrets() {
        assert!(looks_secret("AKIAIOSFODNN7EXAMPLE"));
        assert!(looks_secret("token: ghp_abcdefghijklmnopqrstuvwxyz0123456789"));
        assert!(looks_secret("-----BEGIN OPENSSH PRIVATE KEY-----\nabc"));
        assert!(looks_secret("4111 1111 1111 1111"));
        assert!(!looks_secret("4111 1111 1111 1112"));
        assert!(!looks_secret("hello world"));
        assert!(!looks_secret("call me at 555 123 4567"));
    }

    #[test]
    fn password_mentions() {
        assert!(mentions_password("staging: admin / Password1"));
        assert!(mentions_password("pwd: hunter2"));
        assert!(mentions_password("The PASSWORD is in the vault"));
        assert!(!mentions_password("passport photo"));
        assert!(!mentions_password("bypass the cache"));
        assert!(!mentions_password(&format!("password {}", "x".repeat(400))));
    }

    #[test]
    fn sensitive_items_can_be_kept_briefly() {
        let never = PrivacyFilter::new(&Privacy::default());
        assert_eq!(never.decide_text("AKIAIOSFODNN7EXAMPLE"), Verdict::Ignore(IgnoreReason::Secret));
        assert_eq!(never.decide_text("hello"), Verdict::Save);

        let brief = PrivacyFilter::new(&Privacy {
            sensitive_expiry: "5m".into(),
            ignore_patterns: vec!["(?i)internal".into()],
            ..Privacy::default()
        });
        assert_eq!(brief.decide_text("AKIAIOSFODNN7EXAMPLE"), Verdict::KeepBriefly(IgnoreReason::Secret, 300_000));
        // The user's own pattern always wins, even over a secret.
        assert!(matches!(
            brief.decide_text("internal AKIAIOSFODNN7EXAMPLE"),
            Verdict::Ignore(IgnoreReason::Pattern(_))
        ));
        // Concealed markers can be kept briefly; excluded apps never are.
        let types = vec!["org.nspasteboard.ConcealedType".to_string()];
        assert!(matches!(
            brief.verdict(brief.check_types(&types, None)),
            Verdict::KeepBriefly(IgnoreReason::Concealed(_), _)
        ));
        let plain = vec!["public.utf8-plain-text".to_string()];
        let excluded = brief.check_types(&plain, Some("com.1password.1password"));
        assert!(matches!(brief.verdict(excluded), Verdict::Ignore(IgnoreReason::ExcludedApp(_))));
        // A bad duration means "never save", not "keep forever".
        let bad = PrivacyFilter::new(&Privacy { sensitive_expiry: "soon".into(), ..Privacy::default() });
        assert_eq!(bad.decide_text("AKIAIOSFODNN7EXAMPLE"), Verdict::Ignore(IgnoreReason::Secret));
    }

    #[test]
    fn custom_patterns() {
        let p = Privacy { ignore_patterns: vec!["(?i)internal only".into(), "([".into()], ..Privacy::default() };
        let f = PrivacyFilter::new(&p);
        assert!(f.check_text("this is INTERNAL ONLY").is_some());
        assert!(f.check_text("public").is_none());
    }
}
